assumptionLibraryBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "assumptionLibraryBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "AssumptionsLab",
                name = "assumptionLibrary",
                version = c(1,2,0),
                options = options,
                results = assumptionLibraryResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Assumption Library
#'
#' 
#' @param data .
#' @param category .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$normality} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$normalityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normalityGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$homoscedasticity} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$homoscedasticityGroupTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$homoscedasticityGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$homoscedasticityRegTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$homoscedasticityGuide3} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$linearity} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$linearityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$linearityGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$independence} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$independenceTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$independenceGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$multicollinearity} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$multicollinearityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$multicollinearityGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$influence} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$influenceTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$influenceGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$sphericity} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$sphericityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sphericityGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$proportionalOdds} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$proportionalOddsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$proportionalOddsGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$independenceIrrelevantAlternatives} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$independenceIrrelevantAlternativesTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$independenceIrrelevantAlternativesGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$countModels} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$countModelsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$countModelsGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$robust} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$robustTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$robustGuide2} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a text \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$normalityTable$asDF}
#'
#' \code{as.data.frame(results$normalityTable)}
#'
#' @export
assumptionLibrary <- function(
    data,
    category = "all") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("assumptionLibrary requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- assumptionLibraryOptions$new(
        category = category)

    analysis <- assumptionLibraryClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

